    // MARK: - Privacy (TR)

    private static let privacyTurkish: [LegalSection] = [
        LegalSection(id: "1", title: "1. Giriş", body: "Bu Gizlilik Politikası, Sophia'nın (\"biz\", \"bizim\" veya \"Uygulama\") kişisel bilgilerinizi nasıl topladığını, kullandığını ve koruduğunu açıklamaktadır. Gizliliğinizi korumaya ve verilerinizi şeffaf bir şekilde işlemeye kararlıyız."),
