    // MARK: - Privacy (CS)

    private static let privacyCzech: [LegalSection] = [
        LegalSection(id: "1", title: "1. Úvod", body: "Tyto zásady ochrany osobních údajů popisují, jak Sophia („my“, „naše“ nebo „aplikace“) shromažďuje, používá a chrání vaše osobní údaje. Zavázali jsme se chránit vaše soukromí a nakládat s vašimi údaji transparentně."),
        LegalSection(id: "2", title: "2. Shromážděná data", body: "Sophia je navržena s ohledem na minimalizaci dat. Aplikace ve vašem zařízení ukládá:\n\n- Váš pokrok v kurzech a kvízech\n- Vaše preference (zájmy, cíle)\n- Vaše série (po sobě jdoucí dny používání)\n- Vaše oblíbené kurzy\n\nTato místní data nejsou přenášena na naše servery.\n\nAplikace také odesílá anonymní události používání do Mixpanelu (region EU), aby pochopila, jak se aplikace používá, a vylepšila ji. Tyto události nezahrnují vaše jméno, e-mail ani osobní obsah.\n\nPokud odešlete zpětnou vazbu prostřednictvím formuláře v aplikaci v Nastavení, vaše zpráva a pokud je uvedena, vaše e-mailová adresa se přenese do Formspree, abychom mohli odpovědět. Technické informace (verze aplikace, jazyk, zařízení) jsou připojeny automaticky."),
        LegalSection(id: "3", title: "3. Údaje o předplatném", body: "Pokud si předplatíte prémiový tarif, transakce je zpracována výhradně společností Apple prostřednictvím App Store. Nemáme přístup k vašim platebním údajům (číslo karty, fakturační adresa). Potvrzení o stavu vašeho předplatného dostáváme pouze prostřednictvím RevenueCat, našeho partnera pro správu předplatného."),
